public final class RoomPlanActivity extends Activity {
 float[][] a;float h;boolean preview,manual;Plan view;TextView info;boolean orbit=false;float angle=.65f, tilt=.65f;
 String tr(String en,String fr,String ar){String l=getResources().getConfiguration().getLocales().get(0).getLanguage();return l.equals("ar")?ar:l.equals("fr")?fr:en;}
 int dp(float d){return Math.round(d*getResources().getDisplayMetrics().density);}
 @Override protected void attachBaseContext(android.content.Context base){super.attachBaseContext(Prefs.locale(base));}
 @Override public void onCreate(Bundle b){super.onCreate(b);float[] f=getIntent().getFloatArrayExtra("outline");if(f==null||f.length<6||f.length%2!=0||f.length>60){finish();return;}a=new float[f.length/2][2];for(int i=0;i<a.length;i++){a[i][0]=f[2*i];a[i][1]=f[2*i+1];}if(!RoomMath.valid(a)){finish();return;}h=getIntent().getFloatExtra("height",Float.NaN);preview=getIntent().getBooleanExtra("preview",false);manual=getIntent().getBooleanExtra("manual",false);
 LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff07111e);root.setPadding(dp(16),dp(12),dp(16),dp(12));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16)+i.getSystemWindowInsetLeft(),dp(12)+i.getSystemWindowInsetTop(),dp(16)+i.getSystemWindowInsetRight(),dp(12)+i.getSystemWindowInsetBottom());return i;});
 TextView title=new TextView(this);title.setTextSize(24);title.setTextColor(0xffe5f4f4);title.setText(tr("Room plan","Plan de pièce","مخطط الغرفة"));root.addView(title);
 info=new TextView(this);info.setTextColor(0xffa7f9e8);info.setTextSize(16);root.addView(info);view=new Plan();root.addView(view,new LinearLayout.LayoutParams(-1,0,1));LinearLayout bar=new LinearLayout(this);root.addView(bar);
 btn(bar,"2D",()->{orbit=false;view.invalidate();});btn(bar,"3D",()->{if(!Float.isFinite(h)||h<=0){Toast.makeText(this,tr("Measure the ceiling first.","Mesurez le plafond.","قس ارتفاع السقف أولاً."),Toast.LENGTH_LONG).show();return;}Intent model=new Intent(this,Room3dActivity.class);model.putExtra("outline",RoomMath.flatten(a));model.putExtra("height",h);startActivity(model);});btn(bar,tr("PDF","PDF","PDF"),()->{if(preview){Toast.makeText(this,tr("Confirm scan first.","Validez le scan.","أكد المسح أولاً."),Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"RibhMeasure-room.pdf");startActivityForResult(i,77);});btn(bar,tr("Back","Retour","رجوع"),()->finish());Button save=new Button(this);save.setText(tr("Save room project","Enregistrer le projet","حفظ مشروع الغرفة"));save.setEnabled(!preview);root.addView(save,new LinearLayout.LayoutParams(-1,dp(52)));save.setOnClickListener(v->saveProject());setContentView(root);
 info.setText(String.format(Locale.US,"%s%.2f m² · %.2f m%s",preview?tr("Preview · ","Aperçu · ","معاينة · "):"",RoomMath.area(a),RoomMath.perimeter(a),Float.isFinite(h)&&h>0?String.format(Locale.US,"\nH %.2f m · %.2f m³",h,RoomMath.area(a)*h):""));
 }
 void saveProject(){if(preview)return;EditText name=new EditText(this);name.setSingleLine(true);name.setHint(tr("Room name","Nom de la pièce","اسم الغرفة"));name.setText(tr("Room","Pièce","غرفة")+" "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new java.util.Date()));new android.app.AlertDialog.Builder(this).setTitle(tr("Save room project","Enregistrer le projet","حفظ مشروع الغرفة")).setView(name).setNegativeButton(android.R.string.cancel,null).setPositiveButton(android.R.string.ok,(d,w)->{String n=name.getText().toString().trim();if(n.isEmpty())n=tr("Room","Pièce","غرفة");try{RoomProjects.save(this,n,a,h,manual);Toast.makeText(this,tr("Project saved","Projet enregistré","تم حفظ المشروع"),Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,tr("Save failed","Échec enregistrement","فشل الحفظ"),Toast.LENGTH_LONG).show();}}).show();}
 void btn(LinearLayout l,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setOnClickListener(v->r.run());l.addView(b,new LinearLayout.LayoutParams(0,dp(54),1));}
 @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=77||res!=RESULT_OK||data==null||data.getData()==null)return;PdfDocument doc=new PdfDocument();try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException("No output");PdfDocument.Page p=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas c=p.getCanvas();c.drawColor(Color.WHITE);Paint t=new Paint(Paint.ANTI_ALIAS_FLAG);t.setColor(Color.BLACK);t.setTextSize(25);c.drawText("RibhMeasure | Room plan",38,55,t);t.setTextSize(14);c.drawText(String.format(Locale.US,"Area %.2f m2   Perimeter %.2f m",RoomMath.area(a),RoomMath.perimeter(a)),38,84,t);if(Float.isFinite(h)&&h>0)c.drawText(String.format(Locale.US,"Height %.2f m   Volume %.2f m3",h,RoomMath.area(a)*h),38,105,t);c.save();c.translate(35,145);drawPlan(c,525,525,false,false);c.restore();t.setTextSize(11);c.drawText(manual?"User-entered dimensions. Verify before construction.":"Estimated AR measurements. Verify before construction.",38,795,t);doc.finishPage(p);doc.writeTo(out);Toast.makeText(this,tr("PDF exported","PDF exporté","تم تصدير PDF"),Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,tr("PDF export failed","Échec export PDF","فشل تصدير PDF"),Toast.LENGTH_LONG).show();}finally{try{doc.close();}catch(Exception ignored){}}}
 void drawPlan(Canvas c,int w,int height,boolean three,boolean dark){Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);int line=dark?0xff21e0c2:0xff007a73,txt=dark?0xffe5f4f4:0xff07111e;float[][] base=new float[a.length][2],top=new float[a.length][2];float mx=0,mz=0;for(float[] q:a){mx+=q[0];mz+=q[1];}mx/=a.length;mz/=a.length;float minX=Float.POSITIVE_INFINITY,minY=minX,maxX=Float.NEGATIVE_INFINITY,maxY=maxX;
 for(int j=0;j<a.length;j++){float x=a[j][0]-mx,z=a[j][1]-mz;float xx=three?(float)(x*Math.cos(angle)-z*Math.sin(angle)):x,zz=three?(float)((x*Math.sin(angle)+z*Math.cos(angle))*tilt):z;float yy=three?zz-h*.5f:zz; base[j]=new float[]{xx,zz};top[j]=new float[]{xx,yy};minX=Math.min(minX,xx);maxX=Math.max(maxX,xx);minY=Math.min(minY,Math.min(zz,yy));maxY=Math.max(maxY,Math.max(zz,yy));}
 float scale=Math.min((w-90f)/Math.max(.1f,maxX-minX),(height-90f)/Math.max(.1f,maxY-minY));if(scale<=0)return;for(int j=0;j<a.length;j++){base[j][0]=(base[j][0]-(minX+maxX)/2)*scale+w/2f;base[j][1]=(base[j][1]-(minY+maxY)/2)*scale+height/2f;top[j][0]=(top[j][0]-(minX+maxX)/2)*scale+w/2f;top[j][1]=(top[j][1]-(minY+maxY)/2)*scale+height/2f;}
 Path floor=new Path();for(int j=0;j<base.length;j++){if(j==0)floor.moveTo(base[j][0],base[j][1]);else floor.lineTo(base[j][0],base[j][1]);}floor.close();p.setStyle(Paint.Style.FILL);p.setColor(dark?0xff123c40:0xffe3f5f2);c.drawPath(floor,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(line);c.drawPath(floor,p);
 if(three){for(int j=0;j<a.length;j++){int k=(j+1)%a.length;Path wall=new Path();wall.moveTo(base[j][0],base[j][1]);wall.lineTo(base[k][0],base[k][1]);wall.lineTo(top[k][0],top[k][1]);wall.lineTo(top[j][0],top[j][1]);wall.close();p.setStyle(Paint.Style.FILL);p.setColor(0x5521e0c2);c.drawPath(wall,p);p.setStyle(Paint.Style.STROKE);p.setColor(line);c.drawPath(wall,p);}}
 else {p.setStyle(Paint.Style.FILL);p.setTextSize(15);p.setTextAlign(Paint.Align.CENTER);for(int j=0;j<a.length;j++){int k=(j+1)%a.length;float x=(base[j][0]+base[k][0])/2,y=(base[j][1]+base[k][1])/2;String t=String.format(Locale.US,"%.2f m",Math.hypot(a[j][0]-a[k][0],a[j][1]-a[k][1]));p.setColor(dark?0xff07111e:Color.WHITE);float tw=p.measureText(t)/2+5;c.drawRoundRect(x-tw,y-15,x+tw,y+5,5,5,p);p.setColor(txt);c.drawText(t,x,y,p);}}
 }
 final class Plan extends View{float last;Plan(){super(RoomPlanActivity.this);setContentDescription("Room plan");}@Override protected void onDraw(Canvas c){drawPlan(c,getWidth(),getHeight(),orbit,true);}@Override public boolean performClick(){super.performClick();return true;}@Override public boolean onTouchEvent(android.view.MotionEvent e){if(!orbit)return super.onTouchEvent(e);if(e.getAction()==MotionEvent.ACTION_DOWN){last=e.getX();return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){angle+=(e.getX()-last)*.012f;last=e.getX();invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){performClick();return true;}return true;}}
}
